const src = $json.body ?? $json;
const MODO_PRUEBA = true; // true: todos los correos salen al analista, no al cliente
const EMAIL_ANALISTA = 'analista@tuempresa.com';
const limpio = (v) => (typeof v === 'string' ? v.trim() : v);
const caso = {
  id_caso: limpio(src.id_caso) || '',
  submerchant_id: limpio(src.submerchant_id) || '',
  submerchant_nombre: limpio(src.submerchant_nombre) || '',
  tipo_cliente: String(limpio(src.tipo_cliente) || 'submerchant').toLowerCase(),
  monto: Number(String(src.monto ?? '').replace(',', '.')),
  moneda: String(limpio(src.moneda) || '').toUpperCase(),
  codigo_motivo: limpio(src.codigo_motivo) || '',
  descripcion: limpio(src.descripcion) || '',
  fecha_contracargo: limpio(src.fecha_contracargo) || '',
  email_contacto: limpio(src.email_contacto) || '',
  origen: $json.body ? 'webhook' : 'sheets',
  modo_prueba: MODO_PRUEBA,
  email_analista: EMAIL_ANALISTA,
};
const errores = [];
if (!caso.id_caso) errores.push('falta id_caso');
if (!caso.submerchant_id) errores.push('falta submerchant_id');
if (!Number.isFinite(caso.monto) || caso.monto <= 0) errores.push('monto invalido');
if (!['PEN', 'USD'].includes(caso.moneda)) errores.push('moneda no soportada');
if (!caso.codigo_motivo) errores.push('falta codigo_motivo');
if (!['submerchant', 'agrupador', 'facilitador'].includes(caso.tipo_cliente)) errores.push('tipo_cliente invalido');
return { json: { ...caso, valido: errores.length === 0, motivo_invalido: errores.join('; ') } };

const caso = $('Normalizar y validar caso').item.json;
const tc = Number($json.tc_pen_por_usd);
const monto_usd = caso.moneda === 'USD' ? caso.monto : caso.monto / tc;
return { json: { ...caso, tc_pen_por_usd: tc, tc_fuente: $json.tc_fuente, monto_usd: Math.round(monto_usd * 100) / 100 } };

