const caso = $('Enriquecer caso (USD)').item.json;
const ACCIONES = ['COBRAR_AUTOMATICO', 'SOLICITAR_EVIDENCIA', 'ESCALAR_HUMANO', 'DESCARTAR_NO_COBRABLE'];
const LIMITE_AUTOCOBRO_USD = 5000;
const UMBRAL_CONFIANZA = 0.75;
let out = $json.output;
if (typeof out === 'string') {
  const m = out.match(/\{[\s\S]*\}/);
  try { out = m ? JSON.parse(m[0]) : null; } catch (e) { out = null; }}
if (Array.isArray(out)) out = out[0];
let motivo = null;
if ($json.error) motivo = 'Fallo del agente o del Vector Store: ' + (($json.error.message || $json.error) + '').slice(0, 200);
else if (!out || typeof out !== 'object') motivo = 'Respuesta nula o no interpretable del LLM';
else if (!ACCIONES.includes(out.accion)) motivo = 'Accion fuera del catalogo';
else if (typeof out.confianza !== 'number' || out.confianza < UMBRAL_CONFIANZA) motivo = 'Confianza baja o ausente';
else if (out.accion === 'COBRAR_AUTOMATICO' && caso.monto_usd > LIMITE_AUTOCOBRO_USD) motivo = 'Monto supera el limite de autocobro';
else if (out.accion === 'COBRAR_AUTOMATICO' && !out.clausula_referencia) motivo = 'Cobro sin clausula citada';
else if (['COBRAR_AUTOMATICO', 'SOLICITAR_EVIDENCIA'].includes(out.accion) && !out.borrador_correo) motivo = 'Falta borrador de correo';
const accion_final = motivo ? 'ESCALAR_HUMANO' : out.accion;
return { json: { ...caso, agente: out || {}, accion_agente: out ? (out.accion ?? null) : null, accion_final, motivo_control: motivo || '' } };

